    /**
     * Member count grouped by role
     */
    members_by_role?: {
      [key: string]: number;
    };
    /**
     * Total number of linked deals (all linked fundraises)
     */
    total_deals?: number;
    /**
     * Number of currently live deals (open/oversubscribed/closing states)
     */
    live_deals?: number;
    /**
     * Total amount raised across directory-selected deals (one per company), in cents.
     * String to avoid floating-point precision issues.
     *
     */
    total_raised?: string;
    /**
     * Count of distinct investors across directory-selected deals (one per company)
     */
    total_investors?: number;
    /**
     * Count of audit events in the last 30 days for this syndicate
     */
